// 1. Capturamos los datos
const items = $input.all();
const now = DateTime.now(); // Usamos Luxon

// 2. Detector de usuario nuevo
if (items.length === 0 || !items[0].json.timestamp) {
  return [{
    json: {
      pantalla: "MENU_PRINCIPAL",
      reiniciar: true,
      motivo: "NUEVO_O_SIN_DATA"
    }
  }];
}

// 3. Ordenar logs (Luxon para parsear el formato de Google Sheets)
const logs = items.map(item => ({
  ...item.json,
  fechaProcesada: DateTime.fromFormat(item.json.timestamp, "dd/MM/yyyy H:mm:ss")
})).sort((a, b) => b.fechaProcesada.toMillis() - a.fechaProcesada.toMillis());

const ultimoLog = logs[0];
const minutosInactivo = now.diff(ultimoLog.fechaProcesada, 'minutes').minutes;

// Caso: Sesión expirada (> 60 min)
if (minutosInactivo > 60) {
  return [{
    json: {
      pantalla: "MENU_PRINCIPAL",
      reiniciar: true,
      motivo: "SESION_EXPIRADA",
      minutos_inactivo: Math.floor(minutosInactivo)
    }
  }];
}

// Caso: Usuario en flujo activo
// Importante: Retornamos la pantalla donde SE QUEDÓ el usuario
return [{
  json: {
    pantalla: ultimoLog.pantalla || "MENU_PRINCIPAL",
    reiniciar: false,
    minutos_inactivo: Math.floor(minutosInactivo)
  }
}];

// 1. Capturamos TODOS los registros (Asegúrate de cambiar el rango a A2:E5000)
const logs = $input.all();

// 2. Invertimos el arreglo (reverse). 
// Así, la fila 50 (la más nueva) queda en la posición 0, y la fila 2 (la más vieja) al final.
logs.reverse();

// 3. Extraemos las variables. 
// Ahora .find() atrapará siempre el registro más reciente porque busca de arriba hacia abajo.
const tipo = logs.find(item => item.json.pantalla === 'CREAR_SOLICITUD_TIPO')?.json.opcion;
const prioridad = logs.find(item => item.json.pantalla === 'CREAR_SOLICITUD_PRIORIDAD')?.json.opcion;
const descripcion = logs.find(item => item.json.pantalla === 'CREAR_SOLICITUD_DESCRIPCION')?.json.resultado;

// 4. Retornamos el objeto para el nodo de Append Row (Solicitudes)
return {
  id_ticket: "TIC-" + Math.floor(Date.now() / 1000),
  tipo: tipo || "No definido",
  prioridad: prioridad || "No definido",
  descripcion: descripcion || "Sin descripción",
  estado: "Abierto", 
  creado_por: logs[0]?.json.telegram_user || "ID no encontrado",
  fecha_creacion: new Date().toLocaleString("es-CO", { timeZone: "America/Bogota" }) 
};

// 1. Obtenemos todos los registros
const solicitudes = $input.all();

// 2. Filtramos abiertas o en proceso
const misPendientes = solicitudes.filter(item => {

  const estado = (item.json.estado || "").toLowerCase();

  return estado === "abierto" || estado === "abierta" || estado === "en proceso";

});

// 3. Tomamos las últimas 5
const ultimosCinco = misPendientes.reverse().slice(0, 5);

// 4. Si no hay resultados
if (ultimosCinco.length === 0) {

  return [
    {
      json: {
        lista_tickets: "✅ No tienes solicitudes pendientes en este momento."
      }
    }
  ];

}

// 5. Construimos mensaje
let mensajeLista = "";

ultimosCinco.forEach(ticket => {

  const estado = (ticket.json.estado || "").toLowerCase();

  const emoji = estado === "en proceso" ? "🟡" : "🟢";

  mensajeLista += `${emoji} *ID:* \`${ticket.json.id_ticket}\`\n`;
  mensajeLista += `Estado: _${ticket.json.estado}_\n\n`;

});

return [
  {
    json: {
      lista_tickets: mensajeLista
    }
  }
];

const todosLosTickets = $input.all().map(item => item.json);

// eliminar filas vacías
const ticketsValidos = todosLosTickets.filter(ticket => ticket.id_ticket);

// filtrar tickets activos
const ticketsActivos = ticketsValidos.filter(ticket => {
  const estado = (ticket.estado || "").toLowerCase();
  return estado !== "cerrado" && estado !== "cerrada";
});

// tomar últimos 5
const ultimos5 = ticketsActivos.reverse().slice(0, 5);

// si no hay tickets
if (ultimos5.length === 0) {

  return [
    {
      json: {
        mensaje_lista: "📭 Actualmente no tienes solicitudes activas.\n\nPuedes crear una nueva desde el menú principal.",
        tiene_tickets: false
      }
    }
  ];

}

// crear lista
const listaFormateada = ultimos5.map((ticket, index) => {
  return `*${index + 1}.* \`${ticket.id_ticket}\``;
}).join('\n');

return [
  {
    json: {
      mensaje_lista: listaFormateada,
      tiene_tickets: true
    }
  }
];

