const opcionUsuario = parseInt($node["HelpDeskBot Trigger"].json.message.text);
const todosLosTickets = $input.all().map(item => item.json);

// Aplicamos el MISMO filtro que usaste para mostrar la lista
const ticketsActivos = todosLosTickets.filter(ticket => 
  ticket.estado !== 'Cerrado' && ticket.estado !== 'Cerrada'
).reverse().slice(0, 5);

// Buscamos el ticket en la posición (opcion - 1)
const ticketSeleccionado = ticketsActivos[opcionUsuario - 1];

if (!ticketSeleccionado) {
  return { error: true, mensaje: "Opción no válida. Por favor elige un número de la lista." };
}

return {
  error: false,
  id: ticketSeleccionado.id_ticket,
  tipo: ticketSeleccionado.tipo,
  prioridad: ticketSeleccionado.prioridad,
  estado: ticketSeleccionado.estado,
  descripcion: ticketSeleccionado.descripcion
};

const solicitudes = $input.all().map(item => item.json);

let total = solicitudes.length;
let abiertas = 0;
let proceso = 0;
let cerradas = 0;

solicitudes.forEach(s => {

  const estado = (s.estado || "").toLowerCase();

  if (estado === "abierto" || estado === "abierta") abiertas++;
  if (estado === "en proceso") proceso++;
  if (estado === "cerrado" || estado === "cerrada") cerradas++;

});

// Si no hay solicitudes
if (total === 0) {

  return [
    {
      json: {
        reporte: `
📊 *Reporte de solicitudes*

Total de solicitudes: 0

🟢 Abiertas: 0
🟡 En proceso: 0
🔵 Cerradas: 0

Aún no se han registrado solicitudes.
`
      }
    }
  ];

}

return [
  {
    json: {
      reporte: `
📊 *Reporte de solicitudes*

Total de solicitudes: ${total}

🟢 Abiertas: ${abiertas}
🟡 En proceso: ${proceso}
🔵 Cerradas: ${cerradas}
`
    }
  }
];

