const userIdActual = $('HelpDeskBot Trigger').first().json.message.chat.id;

let totalInteracciones = 0;
try {

  totalInteracciones = $('Code in JavaScript7').first().json.total_interacciones_usuario;
} catch (e) {
  totalInteracciones = 0;
}

const solicitudesUsuario = $input.all().filter(item => {
  return String(item.json.creado_por) === String(userIdActual);
});

const totalSolicitudes = solicitudesUsuario.length;

const mapeoTipos = {
  "1": "Soporte técnico",
  "2": "Solicitud administrativa",
  "3": "Consulta general"
};

const resumen = {};

solicitudesUsuario.forEach(item => {
  const sol = item.json;
  const tipoTexto = mapeoTipos[String(sol.tipo)] || "Tipo no identificado";
  const estado = (sol.estado || "Abierto").trim();

  if (!resumen[tipoTexto]) {
    resumen[tipoTexto] = { total: 0, abiertas: 0, proceso: 0, cerradas: 0 };
  }

  resumen[tipoTexto].total++;

  if (estado === "Abierto") resumen[tipoTexto].abiertas++;
  else if (estado === "En proceso") resumen[tipoTexto].proceso++;
  else if (estado === "Cerrado") resumen[tipoTexto].cerradas++;
});

let tipoMasFrecuente = "N/A";
let maxVal = 0;
for (const t in resumen) {
  if (resumen[t].total > maxVal) {
    maxVal = resumen[t].total;
    tipoMasFrecuente = t;
  }
}

let mensaje = `Reporte de solicitudes:\n\n`;
mensaje += `Resumen general\n`;
mensaje += `- Tipo más frecuente: ${tipoMasFrecuente}\n`;
mensaje += `- Total solicitudes: ${totalSolicitudes}\n`;
mensaje += `- Interacciones con el bot: ${totalInteracciones}\n\n`;
mensaje += `Detaille por tipo:\n\n`;

let index = 1;
for (const [tipo, d] of Object.entries(resumen)) {
  mensaje += `${index}. ${tipo}\n`;
  mensaje += `   - Total: ${d.total}\n`;
  mensaje += `   - Abiertas: ${d.abiertas}\n`;
  mensaje += `   - En proceso: ${d.proceso}\n`;
  mensaje += `   - Cerradas: ${d.cerradas}\n\n`;
  index++;
}

if (totalSolicitudes === 0) {
  mensaje = "Actualmente no tienes solicitudes registradas en el sistema.";
}

return [{
  json: {
    mensaje_final: mensaje.trim()
  }
}];

